<!-- This file is generated by AI. -->

<!--
  角色列表: 管理 GSOV 模型 + 参考音频组合。

  列表本身**只展示信息**, 不提供任何就地编辑, 也没有针对单个角色的按钮 —— 一行里塞满输入框
  与按钮会造成很大的认知压力。所有编辑都在「编辑角色」对话框里完成 (点卡片即打开);
  导出与删除在「选择角色」对话框里; 两者的公共列表逻辑在 `voice/` 下。

  ⚠️ 不带 `<style>` 块 —— 类名来自全局 `styles.css`。
-->

<script lang="ts">
  import type { Character, ModelCandidate } from '../commands/voice';
  import { appStore } from '../state/store.svelte';
  import { voiceController } from '../voice/controller';
  import { errorSummary } from '../voice/errorText';
  import Button from './Button.svelte';
  import CharacterEditDialog from './CharacterEditDialog.svelte';
  import Icon from './Icon.svelte';
  import RolePickerDialog from './RolePickerDialog.svelte';

  const tick = $derived(appStore.voiceTick);
  const characters = $derived.by(() => {
    void tick;
    return appStore.voiceCharacters;
  });

  let query = $state('');
  let pickerOpen = $state(false);
  let editTarget = $state<Character | null>(null);
  let error = $state<string | null>(null);
  let models = $state<ModelCandidate[]>([]);
  /** 上一次触发扫描的角色条数, 只在条数变化时重扫 */
  let scannedCount = -1;

  /*
   * 角色条数变化时补一次"参考音频路径"与"整合包内的 v4 权重"扫描。
   * 依赖条数而不是整个数组: 改一个角色的描述不该重扫磁盘。
   */
  $effect(() => {
    const count = characters.length;
    if (count === scannedCount) return;
    scannedCount = count;
    voiceController.primeReferencePaths().catch(() => {});
    void voiceController.listModels().then((found) => (models = found));
  });

  const enabled = $derived(characters.filter((character) => character.enabled && matchesQuery(character, query)));

  async function create(): Promise<void> {
    error = null;
    try {
      const created = await voiceController.createCharacter(`新角色 ${characters.length + 1}`, '');
      // 新建后直接打开编辑对话框, 否则用户看不到自己刚建了什么
      editTarget = created;
      query = '';
    } catch (caught) {
      error = errorSummary(String(caught));
    }
  }

  /**
   * 「选择角色」= 打开挑选对话框, 任何情况下都**不禁用**。
   *
   * **不要先清空**: 勾选状态本来就是对话框的内容, 打开前清空会让对话框里一个都没勾,
   * 而关掉它就等于把所有手动指定的角色一起失效。
   */
  function openPicker(): void {
    error = null;
    pickerOpen = true;
  }

  /** 打开编辑对话框时始终取最新的一份角色数据 */
  function openEditor(id: string): void {
    editTarget = appStore.voiceCharacters.find((item) => item.id === id) ?? null;
  }

  function matchesQuery(character: Character, needle: string): boolean {
    if (!needle.trim()) return true;
    const text = needle.trim().toLowerCase();
    return character.name.toLowerCase().includes(text) || character.id.toLowerCase().includes(text);
  }

  /** 权重路径的可读后缀 (只取文件名) */
  function suffixOf(weights: string | null | undefined): string {
    if (!weights) return '未指定';
    return weights.replace(/\\/g, '/').split('/').pop() ?? weights;
  }
</script>

<div class="character-panel">
  <div class="character-toolbar">
    <input class="ui-input character-search" placeholder="搜索角色…" bind:value={query} />
    <Button appearance="primary" icon="Add" onclick={() => void create()}>新建角色</Button>
    <Button icon="PersonEdit" onclick={openPicker}>选择角色</Button>
  </div>

  {#if error}
    <p class="voice-error">{error}</p>
  {/if}

  <div class="character-list">
    {#if characters.length === 0}
      <p class="voice-dialog-empty">还没有角色。先「新建角色」或导入一份角色配置。</p>
    {/if}
    {#if characters.length > 0 && enabled.length === 0}
      <p class="voice-dialog-empty">没有已启用的角色。点「选择角色」勾选需要参与配音的角色。</p>
    {/if}
    {#each enabled as character (character.id)}
      <div class="character-tile">
        <button type="button" class="character-tile-main" title="点击编辑角色" onclick={() => openEditor(character.id)}>
          <span class="character-tile-name">
            {character.name}
            {#if character.starred}<span class="character-tile-star"><Icon name="StarFilled" /></span>{/if}
          </span>
          <span class="character-tile-meta">
            {character.id} · 参考音频 {character.references.length}{character.description.trim()
              ? ` · ${character.description.trim()}`
              : ''}
          </span>
          <span class="character-tile-models">
            <span class="character-tile-model" title={character.model?.gptWeights ?? '未指定'}>
              GPT {suffixOf(character.model?.gptWeights)}
            </span>
            <span class="character-tile-model" title={character.model?.sovitsWeights ?? '未指定'}>
              SoVITS {suffixOf(character.model?.sovitsWeights)}
            </span>
          </span>
        </button>
      </div>
    {/each}
  </div>

  <RolePickerDialog open={pickerOpen} onClose={() => (pickerOpen = false)} onError={(message) => (error = message)} />

  {#if editTarget}
    <CharacterEditDialog
      character={editTarget}
      {models}
      onClose={() => (editTarget = null)}
      onChanged={(next) => (editTarget = next)}
      onError={(message) => {
        if (message) error = message;
      }}
    />
  {/if}
</div>
